// TH16 v1.00a st04bs.ecl.txt Boss1 (58-102, entry) + Boss1_at (104-171, dependency).
// Source window: Boss1:61 timerReset .. setInterrupt(0,2300,1800,"BossCard1").
const TIME_LIMIT: int = 1924;
const OPENING_BUFFER: int = 120;
const TH16_TALISMAN: int = 528;

// Boss1_at:148 etEx type 8 (ANGLE_ACCEL): a=duration, r=speed gain/frame,
// s=angular velocity. Source speeds up 0.02/frame over 120 frames (Lunatic
// 0.04/60) while turning 1deg/frame (Lunatic 2deg).
// The type 2 birth ANIM is omitted with the birth stage; its -4*speed
// (-2px at 0.5) is folded into sh_dist below.
xformdef SPIRAL_120(omega: angle, accel: fx) {
    set_ang_vel(omega);
    @120 set_accel(accel);
    set_accel(0fx);
    set_ang_vel(0deg);
}

xformdef SPIRAL_60(omega: angle, accel: fx) {
    set_ang_vel(omega);
    @60 set_accel(accel);
    set_accel(0fx);
    set_ang_vel(0deg);
}

// Boss1_484/Boss1_632: three bursts of Boss1_at(0,...) async + Boss1_at(1,...)
// sync, each followed by wait(10). Both emitters fire the same volley tick.
sub fire_burst(volleys: int, vwait: int) {
    var base: int = 16384;  // Boss1_at:151 %E = 1.570796 rad
    var step: int = 546;    // Boss1_at: %C = 0.05235988 rad (3deg)
    for v in 0..volleys {
        sh_angle(0, (base + v*step) as angle, 0deg);
        sh_angle(1, (base - v*step) as angle, 0deg);
        sh_fire(0);
        sh_fire(1);
        wait(vwait);
    }
}

// moveRand(60,4,1.0) sample: limit rect x[-140,140] y[96,160]
// (Boss:29 moveLimit(0,128,280,64)); direction inner zone is +-70 / 112..144.
// int slot0 = next-step count; fx0/1 = logical unit vector.
sub card_arm_next_step() {
    var k: int = self_int(0)+1;
    set_self_int(0, k);
    var speed: fx = 0fx;
    if k < 60 { speed = (60-k) as fx / 60; }
    var nx: fx = $self_x+self_fx(0)*speed;
    var ny: fx = $self_y+self_fx(1)*speed;
    if nx < -140fx { nx = -140fx; }
    if nx > 140fx { nx = 140fx; }
    if ny < 96fx { ny = 96fx; }
    if ny > 160fx { ny = 160fx; }
    move_vel_xy(0, nx-$self_x, ny-$self_y, EASE_LINEAR);
}

sub card_begin_angle(a: angle) {
    set_self_fx(0, cos(a));
    set_self_fx(1, sin(a));
    set_self_int(0, 0);
    card_arm_next_step();
}

sub card_move_rand() {
    var r: int = rand(65536)-32768;
    var a: int = r/3;
    if $self_x < -70fx {
        a = r/3;
    } else if $self_x > 70fx {
        a = r/3+32768;
        if a > 32768 { a = a-65536; }
    } else {
        a = r/4;
        var choose: int = rand(65536)%3;
        if $player_x > $self_x {
            if choose == 0 { a = a+32768; }
        } else {
            if choose != 0 { a = a+32768; }
        }
    }
    if $self_y < 112fx {
        if a < 0 { a = -a; }
    } else if $self_y > 144fx {
        if a < 0 { a = -a; }
        a = -a;
    }
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    card_begin_angle(a as angle);
}

sub card_wait(frames: int) {
    for i in 0..frames {
        wait(1);
        card_arm_next_step();
    }
}

async sub source_enemy() {
    // Entry state (Boss:14 movePos(0,128), :27-29 boxes/limit); spawned at (0,128).
    set_invuln(65535);
    set_hurtbox(20fx);  // Boss:27 setHurtbox(40,40)
    set_hitbox(24fx);   // Boss:28 setHitbox(48,48)
    // Boss1:75 wait(60) after the omitted stars/dropSeason/anm/sound lines.
    wait(60);

    var rank: int = global(GVAR_RANK);
    var ways: int = 8;      // Boss1_at:110-117 etCount
    var volleys: int = 5;   // Boss1_at:152 diffI(F,5,5,5,6)
    var vwait: int = 10;    // Boss1_at:158-165 wait
    if rank == RANK_NORMAL { ways = 14; }
    if rank == RANK_HARD { ways = 18; }
    if rank == RANK_LUNATIC { ways = 18; volleys = 6; vwait = 8; }

    // Boss1_at:107-149 emitter config (identical for both slots except the
    // signed direction); etDist 32 minus ANIM 4*0.5 = 30.
    sh_reset(0);
    sh_reset(1);
    sh_sprite(0, TH16_TALISMAN, 2);   // etSprite(11,2)
    sh_sprite(1, TH16_TALISMAN, 2);
    sh_ring(0, 1);                    // etAim(3) fixed-direction ring
    sh_ring(1, 1);
    sh_count(0, ways, 1);
    sh_count(1, ways, 1);
    sh_speed(0, 0.5fx, 0fx);          // etSpeed(0.5,1.0), M=1 -> s0
    sh_speed(1, 0.5fx, 0fx);
    sh_offset(0, 0fx, -16fx);         // etOffset(0,-16)
    sh_offset(1, 0fx, -16fx);
    sh_dist(0, 30fx);                 // etDist(32) - 4*0.5
    sh_dist(1, 30fx);
    if rank == RANK_LUNATIC {
        sh_xform(0, SPIRAL_60(2deg, 0.04fx));
        sh_xform(1, SPIRAL_60(0deg - 2deg, 0.04fx));
    } else {
        sh_xform(0, SPIRAL_120(1deg, 0.02fx));
        sh_xform(1, SPIRAL_120(0deg - 1deg, 0.02fx));
    }

    // Boss1_420/Boss1_804: infinite cycle until the segment interrupt.
    loop {
        for b in 0..3 {
            fire_burst(volleys, vwait);
            wait(10);
        }
        card_move_rand();   // Boss1:88 moveRand(60,4,1.0)
        card_wait(60);      // Boss1:98 wait([-1]) = 60 all four ranks
    }
}

async sub pattern() {
    wait(OPENING_BUFFER);
    _ = spawn_enemy(0fx, 128fx, 1000, 0, 0, 0, source_enemy);
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
